import subprocess,json,datetime
code='import json,time,datetime,urllib.parse\nfrom playwright.sync_api import sync_playwright\ndef urlclean(u):\n p=urllib.parse.urlparse(u);return p.scheme+\'://\'+p.netloc+p.path\nwith sync_playwright() as pw:\n browser=pw.chromium.connect_over_cdp(\'http://127.0.0.1:9222\',timeout=10000)\n pages=[p for c in browser.contexts for p in c.pages]\n page=next(p for p in pages if \'firefly.adobe.com\' in p.url)\n page.locator(\'#model\').click(timeout=10000);page.wait_for_timeout(1000)\n print(json.dumps({\'model_menu\':page.locator(\'[role="option"],sp-menu-item\').evaluate_all(\'(els)=>els.map(e=>({tag:e.tagName,role:e.getAttribute("role"),text:e.innerText,label:e.getAttribute("aria-label"),value:e.getAttribute("value")}))\')},ensure_ascii=False))\n\n result=[]\n for c in browser.contexts:\n  for p in c.pages:\n   if p.is_closed():continue\n   try:\n    body=p.locator(\'body\').inner_text(timeout=6000)[:14000]\n    controls=p.locator(\'button,input,textarea,select,[role="combobox"],[role="textbox"]\').evaluate_all(\'(els)=>els.map(e=>({tag:e.tagName,role:e.getAttribute("role"),type:e.type,id:e.id,name:e.getAttribute("name"),text:e.innerText?.slice(0,140),placeholder:e.getAttribute("placeholder"),aria:e.getAttribute("aria-label")}))\')\n    result.append({\'url\':urlclean(p.url),\'title\':p.title(),\'text\':body,\'controls\':controls})\n   except Exception as e:result.append({\'url\':urlclean(p.url),\'error_class\':type(e).__name__})\n print(json.dumps({\'pages\':result},ensure_ascii=False))\n'
r=subprocess.run(['docker','exec','adobe-three-arm-web-20261027','python','-c',code],capture_output=True,text=True,timeout=95)
print(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'returncode':r.returncode,'browser':[json.loads(x) for x in r.stdout.splitlines() if x.startswith('{')] if r.returncode==0 else None,'error_class':'browser_command_failed' if r.returncode else None,'error_tail':r.stderr[-650:] if r.returncode else None},ensure_ascii=False))
